/// <summary>
/// MPJ_31513 Invoicing Design
/// </summary>
[ExtensionOf(classStr(SalesPackingSlipJournalPost))]
final class METSalesPackingSlipJournalPost_Extension
{   
    

}

Method.Source:
    /// <summary>
    /// MPJ_31513 Invoicing Design
    /// Post and print invoice when packing slip posted.
    /// </summary>
    public void postJournalPost()
    {
        next postJournalPost();
       
        //this.postInvoice(); // Commented out as per new requirement in Bug 289957 to not post invoice automatically, keeping the record for history/future use if needed.

        CustPackingSlipTrans custPackingSlipTransLocal;
        custPackingSlipJour custPackingSlipJourLocal = formletterJournal.TableId == tableNum(custPackingSlipJour) ? formletterJournal : custPackingSlipJour;

        select firstonly custPackingSlipTransLocal
            where custPackingSlipTransLocal.salesId == custPackingSlipJourLocal.salesId
                && custPackingSlipTransLocal.packingSlipId == custPackingSlipJourLocal.packingSlipId
                && custPackingSlipTransLocal.DeliveryDate == custPackingSlipJourLocal.DeliveryDate;

        if (custPackingSlipTransLocal.RecId)
        {
            ttsbegin;
            this.metUpdateLoadIdAndShipmentId(custPackingSlipTransLocal);
            ttscommit;
        }
    }

    public void metUpdateLoadIdAndShipmentId(CustPackingSlipTrans _packingSlipTrans)
    {
        InventTrans                     inventTrans;
        InventTransOrigin               inventTransOrigin;
        WMSOrderTrans                   wmsOrderTrans;
        METSalesOrderShipmentLoadLines  shipmentLoadLines;
        METSalesOrderShipmentLoadHeader shipmentLoadHeader;
        CustPackingSlipJour             custPackingSlipJour;

        update_recordset custPackingSlipJour
            setting METLoadId     = shipmentLoadHeader.LoadId,
                    METShipmentId = shipmentLoadHeader.ShipmentId
                where custPackingSlipJour.SalesId           == _packingSlipTrans.salesId
                       && custPackingSlipJour.packingSlipId        == _packingSlipTrans.packingSlipId
                       && custPackingSlipJour.DeliveryDate         == _packingSlipTrans.DeliveryDate
                       && custPackingSlipJour.METLoadId           == ''
                       && custPackingSlipJour.METShipmentId       == ''
            join shipmentLoadHeader
            exists join shipmentLoadLines
                where shipmentLoadLines.ShipmentId == shipmentLoadHeader.ShipmentId
            exists join wmsOrderTrans
                where wmsOrderTrans.RecId == shipmentLoadLines.WMSOrderTransRecId
                    && wmsOrderTrans.InventTransId == _packingSlipTrans.InventTransId
            exists join inventTransOrigin
                where inventTransOrigin.InventTransId == wmsOrderTrans.InventTransId
            exists join inventTrans
                where inventTrans.InventTransOrigin == inventTransOrigin.RecId
                   && inventTrans.PackingSlipId          == _packingSlipTrans.packingSlipId
                   && inventTrans.PickingRouteId     == wmsOrderTrans.RouteId;
    }

    /// <summary>
    /// MPJ_31513 Invoicing Design
    /// Post and print invoice when packing slip posted.
    /// </summary>
    public void postInvoice()
    {
        TmpFrmVirtual tmpFrmVirtual;

        tmpFrmVirtual.TableNum = custPackingSlipJour.TableId;
        tmpFrmVirtual.RecordNo = custPackingSlipJour.RecId;
        tmpFrmVirtual.insert();

        List packingSlipList = new List(Types::Record);
        packingSlipList.addEnd(tmpFrmVirtual);

        SalesFormLetter salesFormLetter = SalesFormLetter::construct(DocumentStatus::Invoice);

        SalesTable salesTable = custPackingSlipJour.salesTable();

        salesFormLetter.salesTable  (salesTable);
        salesFormLetter.transDate   (salesParmTable.TransDate);
        salesFormLetter.specQty     (SalesUpdate::PackingSlip);
        salesFormLetter.proforma    (NoYes::No);             
        salesFormLetter.chooseLines(true);
        salesFormLetter.selectFromJournal(packingSlipList.pack());        
        salesFormLetter.run();        
        
    }
